// src/config.ts
export const config = { maxAttempts: 5, graceMinutes: 15 };

// src/attempts.ts
export const canSubmit = (s: { attemptsUsed: number }) => s.attemptsUsed < config.maxAttempts;

// src/attempts.test.ts
test("a course can lower the attempt limit", () => {
  config.maxAttempts = 3;
  expect(canSubmit({ attemptsUsed: 3 })).toBe(false);
});
test("a learner who used 4 of 5 attempts can still submit", () => {
  expect(canSubmit({ attemptsUsed: 4 })).toBe(true);
});

$ npx vitest run src/attempts.test.ts
 FAIL  src/attempts.test.ts > a learner who used 4 of 5 attempts can still submit
AssertionError: expected false to be true

$ npx vitest run src/attempts.test.ts -t "4 of 5"
 Tests  1 passed | 1 skipped (2)

Statement: "The second test fails in the full run because the first test changed the shared config object and nothing restores it before the second test runs."

